import numpy as np
from scipy.optimize import least_squares
def model(q,t,P):
    k1,k2=q[0],q[1]
    B=[]
    for i in range(4):
        B+= [P**i, P**i*t, P**i*np.exp(-k1*t), P**i*np.exp(-k2*t)]
    B=np.array(B).T
    return B
def resid(q):
    B=model(q,t,P)
    c=np.linalg.lstsq(B,dP_dt,rcond=None)[0]
    return B@c-dP_dt
best=None
for k1 in [0.1,0.3,0.5,1.0]:
  for k2 in [0.05,0.2,0.8,1.5]:
    try:
      r=least_squares(resid,[k1,k2],bounds=([0.001,0.001],[5,5]))
      nm=np.mean(r.fun**2)/np.var(dP_dt)
      if best is None or nm<best[0]: best=(nm,r.x)
